INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3350, 'hygiene', '/ˈhaɪdʒiːn/', 'noun', '{"zh-TW":["衛生"],"en":["conditions or practices conducive to maintaining health"]}', NULL, 'personal/food hygiene', '[{"en":"Good hygiene is essential in food preparation.","zh-TW":"良好的衛生對食品製備至關重要。"},{"en":"The restaurant was closed due to poor hygiene.","zh-TW":"這家餐廳因衛生不合格而關閉。"}]', '{"noun":"hygiene","adjective":"hygienic"}', NULL, 3, 3350, NULL),
(3351, 'hype', '/haɪp/', 'noun, verb', '{"zh-TW":["炒作；大肆宣傳"],"en":["excessive publicity or promotion"]}', NULL, 'media hype / live up to the hype / hype up', '[{"en":"The product failed to live up to the hype.","zh-TW":"該產品未能達到宣傳的效果。"},{"en":"The media hyped the event for weeks.","zh-TW":"媒體連續幾週大肆炒作這個活動。"}]', '{"noun":"hype","verb":"hype","adjective":"hyped"}', NULL, 1, 3351, NULL),
(3352, 'hypercare', '/ˈhaɪpərkeər/', 'noun', '{"zh-TW":["超強支援期；上線後密集支援"],"en":["an intensive support period immediately after a system goes live"]}', NULL, 'hypercare period / hypercare support / provide hypercare', '[{"en":"The team remained on-site during the hypercare period.","zh-TW":"團隊在超強支援期間留在現場。"},{"en":"Hypercare ensures issues are resolved quickly after go-live.","zh-TW":"超強支援確保上線後快速解決問題。"}]', NULL, NULL, 3, 3352, NULL),
(3353, 'hyperparameter', '/ˈhaɪpərˌpærəmɪtər/', 'noun', '{"zh-TW":["超參數"],"en":["a parameter whose value is set before training a machine learning model"]}', NULL, 'tune hyperparameters / optimize hyperparameters / hyperparameter search', '[{"en":"Selecting the right hyperparameters can dramatically improve model performance.","zh-TW":"選擇正確的超參數可以顯著提高模型性能。"},{"en":"Automated hyperparameter tuning reduces trial-and-error in model development.","zh-TW":"自動超參數調整減少了模型開發中的試錯過程。"}]', NULL, NULL, 5, 3353, NULL),
(3354, 'hyperrealism', '/ˌhaɪpərˈrɪəlɪzəm/', 'noun', '{"zh-TW":["超寫實主義"],"en":["a genre of painting and sculpture resembling high-resolution photographs"]}', NULL, 'hyperrealism painting / hyperrealism artist / hyperrealism technique', '[{"en":"Hyperrealism challenges viewers to distinguish art from photography.","zh-TW":"超寫實主義挑戰觀眾區分藝術和攝影之間的差異。"},{"en":"The hyperrealism exhibition attracted visitors for its stunning attention to detail.","zh-TW":"這個超寫實主義展覽以其驚人的細節吸引了遊客。"}]', '{"adjective":"hyperrealist","adverb":"hyperrealistically"}', NULL, 4, 3354, NULL),
(3355, 'hypoglycemia', '/ˌhaɪpəʊɡlaɪˈsiːmiə/', 'noun', '{"zh-TW":["低血糖症"],"en":["an abnormally low level of glucose in the blood"]}', NULL, 'treat hypoglycemia / severe hypoglycemia / hypoglycemia episode', '[{"en":"Hypoglycemia in diabetic patients can be treated with glucose tablets.","zh-TW":"糖尿病患者的低血糖症可用葡萄糖片治療。"},{"en":"Symptoms of hypoglycemia include dizziness, confusion, and sweating.","zh-TW":"低血糖症的症狀包括頭暈、意識混亂和出汗。"}]', '{"adjective":"hypoglycemic"}', NULL, 4, 3355, NULL),
(3356, 'hypothesis', '/haɪˈpɑːθəsɪs/', 'noun', '{"zh-TW":["假設；假說"],"en":["a proposed explanation made as a starting point for investigation"]}', NULL, 'test/support/reject a hypothesis', '[{"en":"The scientist tested her hypothesis through experiments.","zh-TW":"這位科學家通過實驗驗證了她的假說。"},{"en":"Our hypothesis proved to be correct.","zh-TW":"我們的假設被證明是正確的。"}]', '{"noun":"hypothesis","adjective":"hypothetical","verb":"hypothesize"}', NULL, 4, 3356, NULL),
(3357, 'hypothesis testing', '/haɪˈpɒθɪsɪs ˈtestɪŋ/', 'noun', '{"zh-TW":["假設檢驗"],"en":["a statistical procedure for determining if sample data support a hypothesis"]}', NULL, 'conduct hypothesis testing / hypothesis testing methodology / hypothesis testing framework', '[{"en":"Hypothesis testing allows researchers to draw conclusions from sample data.","zh-TW":"假設檢驗允許研究員從樣本數據中得出結論。"},{"en":"A p-value below 0.05 is commonly used to reject the null hypothesis.","zh-TW":"p值低於0.05通常用於拒絕虛無假設。"}]', NULL, NULL, 5, 3357, NULL),
(3358, 'hypothesize', '/haɪˈpɑːθəsaɪz/', 'verb', '{"zh-TW":["假設；假定"],"en":["to form a hypothesis"]}', NULL, 'hypothesize that / hypothesize about', '[{"en":"Researchers hypothesized that the treatment would reduce symptoms.","zh-TW":"研究人員假設這種治療會減輕症狀。"},{"en":"We can hypothesize about possible outcomes.","zh-TW":"我們可以對可能的結果進行假設。"}]', '{"noun":"hypothesis","verb":"hypothesize","adjective":"hypothetical"}', NULL, 4, 3358, NULL),
(3359, 'hypothetical', '/ˌhaɪpəˈθetɪkl/', 'adjective', '{"zh-TW":["假設的；假定的"],"en":["based on an assumption rather than fact"]}', NULL, 'hypothetical situation/scenario/question', '[{"en":"Let me give you a hypothetical scenario.","zh-TW":"讓我給你一個假設的情境。"},{"en":"This is purely hypothetical at this stage.","zh-TW":"在現階段這純粹是假設性的。"}]', '{"noun":"hypothesis","adjective":"hypothetical","verb":"hypothesize"}', NULL, 4, 3359, NULL),
(3360, 'hypothetically', '/''haɪpəˌθetɪkəli/', 'adverb', '{"zh-TW":["假設地；假想地"],"en":["in a hypothetical way; as a supposed or assumed case"]}', NULL, 'hypothetically speaking / think hypothetically / consider hypothetically', '[{"en":"Hypothetically, if costs doubled, the project would still be financially viable.","zh-TW":"假設性地，如果成本翻倍，項目在財務上仍然可行。"},{"en":"She asked the team to think hypothetically about how they would respond to a major disruption.","zh-TW":"她要求團隊假設性地思考他們將如何應對重大中斷。"}]', '{"adjective":"hypothetical"}', NULL, 5, 3360, NULL),
(3361, 'ice', '/aɪs/', 'noun', '{"zh-TW":["冰"],"en":["frozen water"]}', NULL, 'break the ice / on ice', '[{"en":"Let me break the ice with a quick introduction.","zh-TW":"讓我先自我介紹來打破僵局。"},{"en":"The plan is on ice for now.","zh-TW":"這個計畫暫時被擱置了。"}]', '{"noun":"ice","adjective":"icy","verb":"ice"}', NULL, 1, 3361, NULL),
(3362, 'icon', '/ˈaɪkɑːn/', 'noun', '{"zh-TW":["圖標；偶像"],"en":["a symbol on a computer screen; a famous person"]}', NULL, 'click the icon / fashion icon / cultural icon', '[{"en":"Click the icon to open the application.","zh-TW":"點擊圖標打開應用程序。"},{"en":"Steve Jobs was a tech industry icon.","zh-TW":"史蒂夫·賈伯斯是科技產業的偶像。"}]', '{"noun":"icon","adjective":"iconic"}', NULL, 1, 3362, NULL),
(3363, 'idea', '/aɪˈdɪə/', 'noun', '{"zh-TW":["想法；主意"],"en":["a thought or suggestion"]}', NULL, 'good idea / no idea', '[{"en":"That is a great idea for the campaign.","zh-TW":"那是一個很棒的活動點子。"},{"en":"I have no idea why it failed.","zh-TW":"我不知道為什麼失敗了。"}]', '{"noun":"idea","adjective":"ideal","adverb":"ideally","noun2":"idealism"}', NULL, 1, 3363, NULL),
(3364, 'ideal', '/aɪˈdiːəl/', 'adjective, noun', '{"zh-TW":["理想的","理想"],"en":["most suitable; perfect","a standard of perfection"]}', NULL, 'ideal candidate/solution/location', '[{"en":"She is the ideal candidate for this position.","zh-TW":"她是這個職位的理想人選。"},{"en":"This location is ideal for our new office.","zh-TW":"這個地點是我們新辦公室的理想選擇。"}]', '{"noun":"ideal, idealism","adjective":"ideal","adverb":"ideally"}', NULL, 2, 3364, NULL),
(3365, 'ideation', '/ˌaɪdiˈeɪʃən/', 'noun', '{"zh-TW":["構思；想法生成"],"en":["the process of forming new ideas or concepts"]}', NULL, 'ideation process / design ideation / rapid ideation', '[{"en":"The team spent a full day in ideation, generating over a hundred possible solutions.","zh-TW":"團隊花了一整天進行構思，產生了一百多個可能的解決方案。"},{"en":"Ideation is the first step in the design thinking methodology.","zh-TW":"構思是設計思維方法論的第一步。"}]', '{"verb":"ideate","adjective":"ideational"}', NULL, 3, 3365, NULL),
(3366, 'idempotent', '/ɪˈdempətənt/', 'adjective', '{"zh-TW":["冪等的"],"en":["producing the same result regardless of how many times an operation is performed"]}', NULL, 'idempotent operation / idempotent request / make idempotent', '[{"en":"HTTP PUT requests should be idempotent by design.","zh-TW":"HTTP PUT請求在設計上應該是冪等的。"},{"en":"Idempotent operations are essential for safe retries in distributed systems.","zh-TW":"冪等操作對於分散式系統中的安全重試至關重要。"}]', '{"noun":"idempotency"}', NULL, 4, 3366, NULL),
(3367, 'identify', '/aɪˈdentɪfaɪ/', 'verb', '{"zh-TW":["識別；辨認","確認"],"en":["to establish the identity of","to recognize or establish the identity of","to determine"]}', '{"root":{"text":"ident","meaning":"same (相同)"},"suffix":{"text":"-ify","meaning":"make (使)"},"logic":"使確認為同一個，即「識別」。"}', 'identify a problem / identify with / identify the cause; identify a problem/need/trend', '[{"en":"Can you identify the person in this photo?","zh-TW":"你能認出照片中的人嗎？"},{"en":"We need to identify the root cause.","zh-TW":"我們需要找出根本原因。"},{"en":"The police identified the suspect from CCTV footage.","zh-TW":"警方從監控錄像中辨認出了嫌疑人。"},{"en":"We need to identify the root cause of the issue.","zh-TW":"我們需要找出問題的根本原因。"}]', '{"noun":"identification","noun2":"identity","adjective":"identifiable","verb":"identify"}', NULL, 3, 3367, 132),
(3368, 'ideological', '/ˌaɪdiəˈlɒdʒɪkəl/', 'adjective', '{"zh-TW":["意識形態的；思想的"],"en":["relating to a set of beliefs or doctrines"]}', NULL, 'ideological differences / ideological conflict / ideological shift', '[{"en":"Ideological differences made consensus difficult to achieve.","zh-TW":"意識形態差異使達成共識變得困難。"},{"en":"The paper analyzes the ideological underpinnings of the policy.","zh-TW":"論文分析了該政策的意識形態基礎。"}]', '{"noun":"ideology","adverb":"ideologically"}', NULL, 4, 3368, NULL),
(3369, 'idiom', '/''ɪdiəm/', 'noun', '{"zh-TW":["習語；慣用語"],"en":["a group of words established by usage as having a meaning not deducible from individual words"]}', NULL, 'use an idiom / common idiom / understand idioms', '[{"en":"''Break a leg'' is an idiom meaning ''good luck.''","zh-TW":"「Break a leg」是一個意思為「祝好運」的習語。"},{"en":"Learning idioms is an important part of becoming fluent in a new language.","zh-TW":"學習習語是掌握新語言流利性的重要部分。"}]', '{"adjective":"idiomatic"}', NULL, 2, 3369, NULL),
(3370, 'idle capacity', '/ˈaɪdəl kəˈpæsɪti/', 'noun', '{"zh-TW":["閒置產能"],"en":["unused production capacity that could theoretically be utilized"]}', NULL, 'reduce idle capacity / utilize idle capacity', '[{"en":"Idle capacity was used to take on subcontracting work.","zh-TW":"閒置產能被用於承接分包工作。"},{"en":"High idle capacity indicates inefficient resource use.","zh-TW":"高閒置產能表明資源使用效率低下。"}]', NULL, NULL, 5, 3370, NULL),
(3371, 'ignore', '/ɪɡˈnɔːr/', 'verb', '{"zh-TW":["忽視；不理睬"],"en":["to refuse to take notice of"]}', NULL, 'ignore advice/warnings/rules', '[{"en":"You should not ignore the safety warnings.","zh-TW":"你不應該忽視安全警告。"},{"en":"He chose to ignore her complaints.","zh-TW":"他選擇忽視她的投訴。"}]', '{"noun":"ignorance","verb":"ignore","adjective":"ignorant"}', NULL, 2, 3371, NULL),
(3372, 'illiquid', '/ɪˈlɪkwɪd/', 'adjective', '{"zh-TW":["缺乏流動性的；難以變現的"],"en":["(of an asset) not easily converted into cash"]}', NULL, 'illiquid investment / illiquid market / illiquid asset', '[{"en":"Real estate is typically an illiquid asset class.","zh-TW":"房地產通常是缺乏流動性的資產類別。"},{"en":"The fund held too many illiquid positions during the market stress.","zh-TW":"基金在市場壓力期間持有太多難以變現的頭寸。"}]', '{"noun":"illiquidity"}', NULL, 3, 3372, NULL),
(3373, 'illustrate', '/ˈɪləstreɪt/', 'verb', '{"zh-TW":["說明；描繪","說明；闡釋","為...加插圖"],"en":["to explain or make clear by using examples or pictures","to explain by examples","to provide pictures for a book"]}', '{"prefix":{"text":"il-","meaning":"in (在內)"},"root":{"text":"lustr","meaning":"light (光)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使光照入使其清楚，即「說明」。"}', 'illustrate a point / clearly illustrate; illustrate a point/concept', '[{"en":"The graph illustrates the trend clearly.","zh-TW":"圖表清楚地說明了趨勢。"},{"en":"Let me illustrate with an example.","zh-TW":"讓我用一個例子來說明。"},{"en":"The chart illustrates the trend in sales.","zh-TW":"這張圖表說明了銷售趨勢。"},{"en":"Let me illustrate my point with an example.","zh-TW":"讓我用一個例子來說明我的觀點。"}]', '{"noun":"illustration","noun2":"illustrator","verb":"illustrate","adjective":"illustrative"}', NULL, 4, 3373, NULL),
(3374, 'image', '/ˈɪmɪdʒ/', 'noun', '{"zh-TW":["形象；圖像"],"en":["the impression people have of a person or company; a picture"]}', NULL, 'brand/public/corporate image', '[{"en":"The company is trying to improve its public image.","zh-TW":"公司正在努力改善其公眾形象。"},{"en":"Digital images can be edited easily.","zh-TW":"數位圖像可以輕鬆編輯。"}]', '{"noun":"image, imagery","verb":"imagine","adjective":"imaginary"}', NULL, 2, 3374, NULL),
(3375, 'imagine', '/ɪˈmædʒɪn/', 'verb', '{"zh-TW":["想像"],"en":["to form a mental picture of something"]}', NULL, 'hard to imagine / imagine that', '[{"en":"Imagine how the customer feels.","zh-TW":"想像客戶的感受。"},{"en":"It is hard to imagine life without technology.","zh-TW":"很難想像沒有科技的生活。"}]', '{"verb":"imagine","noun":"imagination","adjective":"imaginative","adjective2":"imaginary"}', NULL, 3, 3375, NULL),
(3376, 'immediate', '/ɪˈmiːdiət/', 'adjective', '{"zh-TW":["立即的；即時的","直接的"],"en":["happening without delay","nearest in time or relationship"]}', NULL, 'immediate action/response/effect', '[{"en":"We need to take immediate action on this matter.","zh-TW":"我們需要對此事立即採取行動。"},{"en":"The immediate effect was a rise in stock prices.","zh-TW":"直接效果是股價上漲。"}]', '{"noun":"immediacy","adjective":"immediate","adverb":"immediately"}', NULL, 3, 3376, 133),
(3377, 'immense', '/ɪˈmens/', 'adjective', '{"zh-TW":["巨大的；龐大的"],"en":["extremely large or great"]}', NULL, 'immense pressure/value/potential', '[{"en":"The project requires an immense amount of resources.","zh-TW":"該項目需要大量資源。"},{"en":"She has immense experience in the field.","zh-TW":"她在該領域有豐富的經驗。"}]', '{"noun":"immensity","adjective":"immense","adverb":"immensely"}', NULL, 3, 3377, NULL),
(3378, 'immigration', '/ˌɪmɪˈɡreɪʃən/', 'noun', '{"zh-TW":["移民；入境審查"],"en":["the process of entering a foreign country"]}', NULL, 'immigration officer / pass through immigration', '[{"en":"Please have your passport ready at immigration.","zh-TW":"請在入境審查時備好護照。"},{"en":"The immigration process took over an hour.","zh-TW":"入境審查過程花了一個多小時。"}]', '{"verb":"immigrate","adjective":"immigrant"}', NULL, 4, 3378, NULL),
(3379, 'immigration card', '/ˌɪmɪˈɡreɪʃən kɑːrd/', 'noun', '{"zh-TW":["入境卡"],"en":["a form filled in by travelers entering a country"]}', NULL, 'complete an immigration card / immigration card requirements', '[{"en":"Please fill out the immigration card before landing.","zh-TW":"請在降落前填寫入境卡。"},{"en":"The immigration card asks for your intended length of stay.","zh-TW":"入境卡詢問您預計停留時間。"}]', NULL, NULL, 5, 3379, NULL),
(3380, 'immigration officer', '/''ɪmɪˈɡreɪʃən ˌɒfɪsər/', 'noun', '{"zh-TW":["移民官；入境審查官"],"en":["an official responsible for controlling the entry of people into a country"]}', NULL, 'speak to an immigration officer / immigration officer check / pass through immigration', '[{"en":"The immigration officer stamped her passport and welcomed her to the country.","zh-TW":"移民官在她的護照上蓋了章，並歡迎她來到這個國家。"},{"en":"Travelers should have all documents ready before approaching the immigration officer.","zh-TW":"旅客在接近移民官之前應準備好所有文件。"}]', NULL, NULL, 5, 3380, NULL),
(3381, 'imminent', '/ˈɪmɪnənt/', 'adjective', '{"zh-TW":["即將發生的；迫在眉睫的"],"en":["about to happen very soon"]}', NULL, 'imminent threat / imminent deadline / imminent layoffs', '[{"en":"An imminent regulatory change forced the company to adapt quickly.","zh-TW":"即將到來的監管變化迫使公司迅速調整。"},{"en":"The imminent product launch required all hands on deck.","zh-TW":"即將到來的產品發佈需要所有人全力以赴。"}]', '{"adverb":"imminently","noun":"imminence"}', NULL, 3, 3381, NULL),
(3382, 'immune', '/ɪˈmjuːn/', 'adjective', '{"zh-TW":["免疫的；不受影響的"],"en":["resistant to; not affected by"]}', NULL, 'immune to / immune system / immune from', '[{"en":"No company is immune to economic downturns.","zh-TW":"沒有公司能免受經濟衰退的影響。"},{"en":"The new policy makes no one immune from accountability.","zh-TW":"新政策使沒有人能免除問責。"}]', '{"noun":"immunity, immunization","adjective":"immune","verb":"immunize"}', NULL, 2, 3382, NULL),
(3383, 'immunization', '/ˌɪmjʊnaɪˈzeɪʃən/', 'noun', '{"zh-TW":["免疫接種；疫苗接種"],"en":["the process of making someone immune to a disease"]}', NULL, 'childhood immunization / immunization schedule', '[{"en":"All children should receive the recommended immunizations.","zh-TW":"所有兒童都應接受建議的免疫接種。"},{"en":"International travel may require additional immunizations.","zh-TW":"國際旅行可能需要額外的免疫接種。"}]', '{"verb":"immunize","noun":"immunity"}', NULL, 4, 3383, NULL),
(3384, 'immunotherapy', '/ɪˌmjuːnəʊˈθerəpi/', 'noun', '{"zh-TW":["免疫療法"],"en":["treatment that uses the body''s immune system to fight disease"]}', NULL, 'cancer immunotherapy / immunotherapy treatment / receive immunotherapy', '[{"en":"Immunotherapy has shown remarkable results in treating certain cancers.","zh-TW":"免疫療法在治療某些癌症方面顯示出顯著效果。"},{"en":"The patient responded well to immunotherapy after conventional treatment failed.","zh-TW":"在常規治療失敗後，患者對免疫療法反應良好。"}]', '{"adjective":"immunotherapeutic"}', NULL, 5, 3384, NULL),
(3385, 'immutable', '/ɪˈmjuːtəbəl/', 'adjective', '{"zh-TW":["不可變的；永久不變的"],"en":["unable to be changed after being created"]}', NULL, 'immutable data / immutable record / immutable infrastructure', '[{"en":"Immutable data structures prevent unexpected side effects in programs.","zh-TW":"不可變的數據結構防止程式中的意外副作用。"},{"en":"Blockchain records are immutable once confirmed by the network.","zh-TW":"區塊鏈記錄一旦被網絡確認就不可改變。"}]', '{"noun":"immutability","adverb":"immutably"}', NULL, 3, 3385, NULL),
(3386, 'impact', '/ˈɪmpækt/', 'noun, verb', '{"zh-TW":["影響；衝擊"],"en":["a strong effect or influence"]}', NULL, 'have an impact on / environmental impact', '[{"en":"The new policy will have a significant impact on small businesses.","zh-TW":"新政策將對小企業產生重大影響。"},{"en":"Climate change impacts everyone.","zh-TW":"氣候變遷影響每個人。"}]', '{"noun":"impact","verb":"impact","adjective":"impactful"}', NULL, 2, 3386, 368),
(3387, 'impact assessment', '/ˈɪmpækt əˈsesmənt/', 'noun', '{"zh-TW":["影響評估"],"en":["an evaluation of the likely effects of a project or policy"]}', NULL, 'conduct an impact assessment / social impact assessment / environmental impact assessment', '[{"en":"Governments require an impact assessment before approving major developments.","zh-TW":"政府在批准重大開發之前需要進行影響評估。"},{"en":"The impact assessment identified significant risks to local biodiversity.","zh-TW":"影響評估識別了對當地生物多樣性的重大風險。"}]', NULL, NULL, 5, 3387, NULL),
(3388, 'impact investing', '/ˈɪmpækt ɪnˈvestɪŋ/', 'noun', '{"zh-TW":["影響力投資"],"en":["investments intended to generate positive social or environmental outcomes alongside returns"]}', NULL, 'engage in impact investing / impact investing fund', '[{"en":"Impact investing targets companies solving environmental and social challenges.","zh-TW":"影響力投資針對解決環境和社會挑戰的公司。"},{"en":"Many institutional investors allocate a portion of assets to impact investing.","zh-TW":"許多機構投資者將部分資產分配到影響力投資。"}]', '{"synonym":"ESG investing","synonym2":"sustainable investing"}', NULL, 5, 3388, NULL),
(3389, 'impactful', '/''ɪmˈpæktfʊl/', 'adjective', '{"zh-TW":["有影響力的；影響深遠的"],"en":["having a major impact or effect; producing a strong impression"]}', NULL, 'impactful message / impactful campaign / impactful leader', '[{"en":"The nonprofit launched an impactful campaign that raised awareness globally.","zh-TW":"這個非營利組織發起了一場在全球提高意識的影響深遠的活動。"},{"en":"She delivered an impactful speech that moved the entire audience.","zh-TW":"她發表了一篇打動了全場觀眾的有影響力的演講。"}]', '{"noun":"impact"}', NULL, 3, 3389, NULL),
(3390, 'impair', '/ɪmˈper/', 'verb', '{"zh-TW":["損害；削弱"],"en":["to weaken or damage something"]}', NULL, 'impair vision/judgment/performance', '[{"en":"Alcohol can impair your judgment.","zh-TW":"酒精會損害你的判斷力。"},{"en":"Noise pollution can impair hearing over time.","zh-TW":"噪音污染長期下來會損害聽力。"}]', '{"noun":"impairment","verb":"impair","adjective":"impaired"}', NULL, 2, 3390, NULL),
(3391, 'impairment', '/ɪmˈpeərmənt/', 'noun', '{"zh-TW":["減值"],"en":["a reduction in the recoverable value of an asset below its carrying value"]}', NULL, 'goodwill impairment / asset impairment / impairment charge / impairment test', '[{"en":"An impairment charge was triggered by falling property values.","zh-TW":"不動產價值下跌引發了減值費用。"},{"en":"The company performed annual goodwill impairment testing.","zh-TW":"公司每年進行商譽減值測試。"}]', '{"verb":"impair","adjective":"impaired"}', NULL, 4, 3391, NULL),
(3392, 'impairment loss', '/ɪmˈpeərmənt lɒs/', 'noun', '{"zh-TW":["減值損失"],"en":["a charge recorded when an asset''s carrying value exceeds its recoverable amount"]}', NULL, 'record an impairment loss / impairment loss test', '[{"en":"An impairment loss of $15 million was recorded after the subsidiary underperformed.","zh-TW":"在子公司表現不佳後，記錄了1500萬元的減值損失。"},{"en":"Annual impairment tests are required under international accounting standards.","zh-TW":"國際會計準則要求每年進行減值測試。"}]', '{"verb":"impair"}', NULL, 5, 3392, NULL),
(3393, 'impairment test', '/ɪmˈpeərmənt test/', 'noun', '{"zh-TW":["減損測試"],"en":["an assessment of whether an asset value has fallen below its carrying amount"]}', NULL, 'conduct an impairment test / annual impairment test', '[{"en":"The annual impairment test showed no reduction in goodwill value.","zh-TW":"年度減損測試顯示商譽價值沒有下降。"},{"en":"Impairment tests are triggered by adverse market or business conditions.","zh-TW":"減損測試由不利的市場或業務條件觸發。"}]', NULL, NULL, 5, 3393, NULL),
(3394, 'impartial', '/''ɪmˈpɑːrʃəl/', 'adjective', '{"zh-TW":["公正的；不偏倚的"],"en":["treating all rivals or disputants equally; fair and just"]}', NULL, 'impartial judge / impartial review / remain impartial', '[{"en":"A successful mediator must remain impartial throughout the negotiation process.","zh-TW":"成功的調解員在整個談判過程中必須保持公正。"},{"en":"The investigation was conducted by an impartial third-party committee.","zh-TW":"調查由一個不偏倚的第三方委員會進行。"}]', '{"adverb":"impartially","noun":"impartiality"}', NULL, 3, 3394, NULL),
(3395, 'impatient', '/ɪmˈpeɪʃnt/', 'adjective', '{"zh-TW":["不耐煩的"],"en":["not willing to wait or unable to tolerate delay"]}', '{"prefix":{"text":"im-","meaning":"not (不)"},"root":{"text":"patient","meaning":"enduring (忍耐)"},"logic":"不能忍耐的，即「不耐煩的」。"}', 'grow impatient / impatient with', '[{"en":"He grew impatient waiting for the bus.","zh-TW":"他等公車等得不耐煩了。"},{"en":"Don''t be so impatient with the children.","zh-TW":"對孩子們不要那麼沒耐心。"}]', '{"noun":"impatience","adverb":"impatiently"}', NULL, 3, 3395, NULL),
(3396, 'impeach', '/ɪmˈpiːtʃ/', 'verb', '{"zh-TW":["彈劾"],"en":["to charge a public official with misconduct"]}', NULL, 'impeach a president / impeachment trial', '[{"en":"Congress voted to impeach the president.","zh-TW":"國會投票彈劾總統。"},{"en":"The impeachment process began.","zh-TW":"彈劾程序開始了。"}]', '{"noun":"impeachment"}', NULL, 3, 3396, NULL),
(3397, 'impeachment', '/ɪmˈpiːtʃmənt/', 'noun', '{"zh-TW":["彈劾；彈劾程序"],"en":["the process of formally charging a public official with misconduct"]}', NULL, 'presidential impeachment / impeachment proceedings / face impeachment', '[{"en":"The legislature initiated impeachment proceedings against the corrupt minister.","zh-TW":"立法機構對腐敗部長啟動了彈劾程序。"},{"en":"Impeachment requires a majority vote in the lower house and a trial in the senate.","zh-TW":"彈劾需要下議院多數票通過並在參議院進行審判。"}]', '{"verb":"impeach","adjective":"impeachable"}', NULL, 4, 3397, NULL),
(3398, 'impeccable', '/''ɪmˈpekəbəl/', 'adjective', '{"zh-TW":["無可挑剔的；完美的"],"en":["in accordance with the highest standards; faultless"]}', NULL, 'impeccable service / impeccable record / impeccable credentials', '[{"en":"The hotel is renowned for its impeccable service and attention to detail.","zh-TW":"這家飯店以其無可挑剔的服務和對細節的關注而聞名。"},{"en":"Her impeccable academic record helped her secure the prestigious scholarship.","zh-TW":"她無可挑剔的學術記錄幫助她獲得了享有盛譽的獎學金。"}]', '{"adverb":"impeccably"}', NULL, 4, 3398, NULL),
(3399, 'impede', '/ɪmˈpiːd/', 'verb', '{"zh-TW":["妨礙；阻礙"],"en":["to delay or prevent something"]}', NULL, 'impede progress/growth/development', '[{"en":"Bureaucracy can impede the progress of reforms.","zh-TW":"官僚主義會妨礙改革的進展。"},{"en":"The construction work impeded traffic flow.","zh-TW":"施工妨礙了交通流暢。"}]', '{"noun":"impediment","verb":"impede"}', NULL, 2, 3399, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3400, 'imperative', '/ɪmˈperətɪv/', 'adjective, noun', '{"zh-TW":["迫切的；必要的","必要的事"],"en":["extremely important and urgent","something vital"]}', NULL, 'it is imperative that / moral imperative', '[{"en":"It is imperative that we act quickly.","zh-TW":"我們迫切需要迅速行動。"},{"en":"Data security is a business imperative.","zh-TW":"數據安全是商業上的當務之急。"}]', '{"noun":"imperative","adjective":"imperative"}', NULL, 4, 3400, NULL),
(3401, 'impetus', '/ˈɪmpɪtəs/', 'noun', '{"zh-TW":["推動力；動力"],"en":["a force that makes something happen or happen more quickly"]}', NULL, 'provide impetus / impetus for change / lose impetus', '[{"en":"The crisis provided the impetus for sweeping regulatory reforms.","zh-TW":"危機為全面的監管改革提供了推動力。"},{"en":"The discovery gave new impetus to research in the field.","zh-TW":"這一發現為該領域的研究注入了新的動力。"}]', NULL, NULL, 3, 3401, NULL),
(3402, 'implement', '/ˈɪmplɪment/', 'verb', '{"zh-TW":["實施；執行","工具；器具"],"en":["to put into effect","to put a plan into action","a tool or instrument"]}', '{"prefix":{"text":"im-","meaning":"in (進入)"},"root":{"text":"ple","meaning":"fill (充滿)"},"suffix":{"text":"-ment","meaning":"result (結果)"},"logic":"充實到行動中，即「實施」。"}', 'implement a plan / implement changes / implement a policy; implement a plan/policy/strategy', '[{"en":"The company will implement the new policy next month.","zh-TW":"公司下個月將實施新政策。"},{"en":"It takes time to implement changes.","zh-TW":"實施變革需要時間。"},{"en":"The government plans to implement new regulations.","zh-TW":"政府計劃實施新的法規。"},{"en":"The changes will be implemented next quarter.","zh-TW":"這些變更將在下個季度實施。"}]', '{"noun":"implementation","verb":"implement"}', NULL, 3, 3402, 33),
(3403, 'implementation', '/ˌɪmplɪmenˈteɪʃən/', 'noun', '{"zh-TW":["實施；執行"],"en":["the process of putting a plan, decision, or system into effect"]}', NULL, 'implementation plan / full implementation / phased implementation / implementation timeline', '[{"en":"The implementation of the new system took six months.","zh-TW":"新系統的實施花了六個月。"},{"en":"A detailed implementation plan was shared with all stakeholders.","zh-TW":"詳細的實施計劃與所有利益相關者分享。"}]', '{"verb":"implement","adjective":"implemented"}', NULL, 5, 3403, 578),
(3404, 'implication', '/ˌɪmplɪˈkeɪʃn/', 'noun', '{"zh-TW":["含義；暗示","影響；後果"],"en":["something suggested without being stated","a possible consequence"]}', NULL, 'have implications for / the implications of', '[{"en":"The findings have serious implications for public health.","zh-TW":"這些發現對公共衛生有嚴重影響。"},{"en":"What are the implications of this decision?","zh-TW":"這個決定有什麼含義？"}]', '{"noun":"implication","verb":"imply, implicate","adjective":"implicit"}', NULL, 4, 3404, NULL),
(3405, 'implicit', '/ɪmˈplɪsɪt/', 'adjective', '{"zh-TW":["含蓄的；隱含的"],"en":["implied though not directly expressed"]}', NULL, 'implicit assumption/understanding/trust', '[{"en":"There was an implicit understanding between the partners.","zh-TW":"合作夥伴之間有一種默契。"},{"en":"The risks are implicit in the contract terms.","zh-TW":"風險隱含在合同條款中。"}]', '{"adjective":"implicit","adverb":"implicitly","noun":"implication"}', NULL, 3, 3405, NULL),
(3406, 'implicit message', '/''ɪmˌplɪsɪt ˌmesɪdʒ/', 'noun', '{"zh-TW":["隱含信息；言外之意"],"en":["a message that is not directly stated but is suggested or implied"]}', NULL, 'understand the implicit message / convey an implicit message / recognize the implicit message', '[{"en":"She recognized the implicit message in his reluctant tone even without explicit words.","zh-TW":"她從他不情願的語氣中識別出了言外之意，即使沒有明確的話語。"},{"en":"Great writers convey implicit messages that readers feel without being told directly.","zh-TW":"偉大的作家傳達讀者感受到但未被直接告知的隱含信息。"}]', '{"adjective":"implicit"}', NULL, 5, 3406, NULL),
(3407, 'implied contract', '/ɪmˈplaɪd ˈkɒntrækt/', 'noun', '{"zh-TW":["默示合約；推定合約"],"en":["a contract formed by actions rather than written agreement"]}', NULL, 'enter an implied contract / terms of an implied contract', '[{"en":"An implied contract can exist even without a written document.","zh-TW":"即使沒有書面文件，默示合約也可以存在。"},{"en":"Accepting the service created an implied contract with the provider.","zh-TW":"接受服務與提供者之間產生了默示合約。"}]', NULL, NULL, 5, 3407, NULL),
(3408, 'imply', '/ɪmˈplaɪ/', 'verb', '{"zh-TW":["暗示；意味著"],"en":["to suggest without stating directly","to suggest something without saying it directly"]}', '{"prefix":{"text":"im-","meaning":"in (在內)"},"root":{"text":"ply","meaning":"fold (折疊)"},"logic":"把意思折藏在裡面，即「暗示」。"}', 'imply that / strongly imply', '[{"en":"Are you implying that I''m wrong?","zh-TW":"你是在暗示我錯了嗎？"},{"en":"The data implies a connection between the two variables.","zh-TW":"數據暗示兩個變數之間有關聯。"},{"en":"Are you implying that I made a mistake?","zh-TW":"你是在暗示我犯了錯嗎？"},{"en":"The data implies a strong correlation.","zh-TW":"數據暗示了很強的相關性。"}]', '{"noun":"implication","adjective":"implicit","verb":"imply"}', NULL, 2, 3408, NULL),
(3409, 'import', '/ˈɪmpɔːrt/', 'noun, verb', '{"zh-TW":["進口；輸入","進口商品"],"en":["to bring goods from another country","goods brought from abroad"]}', NULL, 'import goods/products / import duties', '[{"en":"The country imports most of its oil.","zh-TW":"該國大部分石油依賴進口。"},{"en":"Import duties have been raised by 5%.","zh-TW":"進口關稅提高了5%。"}]', '{"noun":"import, importation, importer","verb":"import"}', NULL, 2, 3409, NULL),
(3410, 'import duty', '/ˈɪmpɔːrt ˈdjuːti/', 'noun', '{"zh-TW":["進口關稅"],"en":["a tax charged on goods brought into a country"]}', NULL, 'pay import duty / import duty exemption', '[{"en":"The import duty on electronics was recently reduced.","zh-TW":"電子產品的進口關稅最近有所降低。"},{"en":"Importers must declare all goods and pay the applicable import duty.","zh-TW":"進口商必須申報所有貨物並繳納適用的進口關稅。"}]', NULL, NULL, 4, 3410, NULL),
(3411, 'import duty exemption', '/ˈɪmpɔːrt ˈdjuːti ɪɡˈzempʃən/', 'noun', '{"zh-TW":["進口關稅豁免"],"en":["freedom from paying import duties under specific conditions"]}', NULL, 'claim an import duty exemption / import duty exemption scheme', '[{"en":"Manufacturers in export zones benefit from import duty exemptions.","zh-TW":"出口區的製造商受益於進口關稅豁免。"},{"en":"An import duty exemption was granted for raw materials used in production.","zh-TW":"對用於生產的原材料給予了進口關稅豁免。"}]', NULL, NULL, 5, 3411, NULL),
(3412, 'import license', '/''ɪmpɔːrt ˌlaɪsəns/', 'noun', '{"zh-TW":["進口許可證"],"en":["official permission required to import certain goods into a country"]}', NULL, 'obtain an import license / import license requirement / apply for an import license', '[{"en":"Importers must obtain an import license before bringing restricted goods into the country.","zh-TW":"進口商在將受限商品帶入該國之前必須獲得進口許可證。"},{"en":"Without a valid import license, the goods were detained at the port.","zh-TW":"沒有有效的進口許可證，貨物在港口被扣押。"}]', NULL, NULL, 5, 3412, NULL),
(3413, 'import quota', '/ˈɪmpɔːrt ˈkwoʊtə/', 'noun', '{"zh-TW":["進口配額"],"en":["a government limit on the quantity of a specific good that can be imported"]}', NULL, 'set an import quota / exceed the import quota', '[{"en":"The government set an import quota on foreign steel.","zh-TW":"政府對外國鋼鐵設定了進口配額。"},{"en":"Import quotas protect domestic industries from foreign competition.","zh-TW":"進口配額保護國內產業免受外國競爭。"}]', '{"plural":"import quotas"}', NULL, 4, 3413, NULL),
(3414, 'import substitute', '/ˈɪmpɔːrt ˈsʌbstɪtjuːt/', 'noun', '{"zh-TW":["進口替代品"],"en":["a domestically produced good that replaces an imported product"]}', NULL, 'develop import substitutes / import substitution policy', '[{"en":"The government promoted domestic production as import substitutes.","zh-TW":"政府推動國內生產作為進口替代品。"},{"en":"Import substitution reduced dependence on foreign suppliers.","zh-TW":"進口替代降低了對外國供應商的依賴。"}]', NULL, NULL, 5, 3414, NULL),
(3415, 'import tariff', '/ˈɪmpɔːrt ˈtærɪf/', 'noun', '{"zh-TW":["進口關稅"],"en":["a tax imposed on goods imported from foreign countries"]}', NULL, 'impose an import tariff / import tariff rate', '[{"en":"The government imposed an import tariff on steel to protect domestic producers.","zh-TW":"政府對鋼鐵徵收進口關稅以保護國內生產商。"},{"en":"Rising import tariffs increased the cost of raw materials.","zh-TW":"不斷上升的進口關稅增加了原材料成本。"}]', NULL, NULL, 5, 3415, NULL),
(3416, 'important', '/ɪmˈpɔːrtənt/', 'adjective', '{"zh-TW":["重要的"],"en":["having great value or significance"]}', NULL, 'most important / important role', '[{"en":"Communication is the most important skill.","zh-TW":"溝通是最重要的技能。"},{"en":"She plays an important role in the project.","zh-TW":"她在專案中扮演重要角色。"}]', '{"adjective":"important","noun":"importance","adverb":"importantly","adjective2":"unimportant"}', NULL, 3, 3416, NULL),
(3417, 'impose', '/ɪmˈpoʊz/', 'verb', '{"zh-TW":["施加；強加","強加；施加","徵收"],"en":["to force something on someone","to establish a tax or fine"]}', '{"prefix":{"text":"im-","meaning":"on (在上)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放在某人身上，即「強加」。"}', 'impose restrictions / impose a fine / impose on; impose restrictions/sanctions/a fine', '[{"en":"The government imposed new taxes on imports.","zh-TW":"政府對進口商品徵收新稅。"},{"en":"I don''t want to impose on your time.","zh-TW":"我不想占用你的時間。"},{"en":"The government imposed new restrictions on imports.","zh-TW":"政府對進口實施了新的限制。"},{"en":"A heavy fine was imposed on the company.","zh-TW":"公司被處以高額罰款。"}]', '{"noun":"imposition","verb":"impose"}', NULL, 2, 3417, NULL),
(3418, 'impress', '/ɪmˈpres/', 'verb', '{"zh-TW":["使印象深刻；使欽佩"],"en":["to make someone feel admiration"]}', NULL, 'impress someone with / be impressed by', '[{"en":"Her presentation impressed the entire board.","zh-TW":"她的報告讓整個董事會印象深刻。"},{"en":"I was very impressed by the quality of the work.","zh-TW":"我對工作的品質印象非常深刻。"}]', '{"noun":"impression","verb":"impress","adjective":"impressive, impressed"}', NULL, 3, 3418, NULL),
(3419, 'impression', '/ɪmˈpreʃən/', 'noun', '{"zh-TW":["曝光次數；印象"],"en":["the number of times an advertisement is displayed to users"]}', NULL, 'ad impression / impression rate / cost per thousand impressions', '[{"en":"The campaign generated 5 million impressions in the first week.","zh-TW":"該活動在第一週產生了500萬次曝光。"},{"en":"Impressions measure how often your content is shown, not clicked.","zh-TW":"曝光次數衡量您的內容顯示頻率，而非點擊頻率。"}]', NULL, NULL, 4, 3419, NULL),
(3420, 'improve', '/ɪmˈpruːv/', 'verb', '{"zh-TW":["改善；提高"],"en":["to make or become better"]}', NULL, 'improve performance/quality/efficiency', '[{"en":"The company needs to improve customer service.","zh-TW":"公司需要改善客戶服務。"},{"en":"His English has improved significantly.","zh-TW":"他的英語有了顯著的進步。"}]', '{"noun":"improvement","verb":"improve","adjective":"improved"}', NULL, 3, 3420, NULL),
(3421, 'improvement', 'ɪmˈpruːvmənt', 'noun', '{"zh-TW":["改善；進步","提高"],"en":["a positive change","progress made"]}', NULL, 'significant improvement/room for improvement', '[{"en":"There is room for improvement in our process.","zh-TW":"我們的流程有改善的空間。"}]', '{"verb":"improve","adjective":"improved","adverb":"improved"}', NULL, 4, 3421, 134),
(3422, 'improvisation', '/ɪmˌprɒvɪˈzeɪʃən/', 'noun', '{"zh-TW":["即興創作；即興表演"],"en":["the action of creating or performing without preparation"]}', NULL, 'musical improvisation / theatrical improvisation / jazz improvisation', '[{"en":"Jazz musicians are celebrated for their ability to improvisation spontaneously.","zh-TW":"爵士音樂家以其即興創作能力而著稱。"},{"en":"Improvisation in theater teaches performers to be present and responsive.","zh-TW":"戲劇中的即興表演教會演員保持當下狀態並靈活回應。"}]', '{"verb":"improvise","adjective":"improvisational"}', NULL, 5, 3422, NULL),
(3423, 'impulse', '/ˈɪmpʌls/', 'noun', '{"zh-TW":["衝動；推動力"],"en":["a sudden strong urge; a driving force"]}', NULL, 'impulse buying / on impulse / impulse purchase', '[{"en":"Impulse buying accounts for 30% of retail sales.","zh-TW":"衝動購買佔零售銷售額的30%。"},{"en":"She bought the dress on impulse.","zh-TW":"她一時衝動買了那件洋裝。"}]', '{"noun":"impulse","adjective":"impulsive","adverb":"impulsively"}', NULL, 3, 3423, NULL),
(3424, 'imputed cost', '/ɪmˈpjuːtɪd kɒst/', 'noun', '{"zh-TW":["隱含成本；計算成本"],"en":["a theoretical cost that is not directly incurred but assigned for accounting or economic purposes"]}', NULL, 'calculate imputed cost / imputed cost of capital / imputed rent', '[{"en":"Imputed costs allow economists to measure the true cost of owner-occupied housing.","zh-TW":"隱含成本使經濟學家能夠衡量業主自住房屋的真實成本。"},{"en":"Failure to account for imputed costs leads to an overestimate of economic profit.","zh-TW":"未能計入隱含成本會導致高估經濟利潤。"}]', NULL, NULL, 4, 3424, NULL),
(3425, 'imputed interest', '/ɪmˈpjuːtɪd ˈɪntrəst/', 'noun', '{"zh-TW":["隱含利息"],"en":["interest that is assumed to be paid even if not explicitly charged"]}', NULL, 'imputed interest calculation / imputed interest income / imputed interest expense', '[{"en":"Tax authorities may impute interest on below-market loans between related parties.","zh-TW":"稅務機關可能對關聯方之間低於市場利率的貸款課徵隱含利息。"},{"en":"The IRS requires that imputed interest be reported as income.","zh-TW":"美國國稅局要求將隱含利息報告為收入。"}]', NULL, NULL, 5, 3425, NULL),
(3426, 'in arrears', '/ɪn əˈrɪərz/', 'adverb', '{"zh-TW":["逾期未付的；拖欠的"],"en":["behind on payments or obligations that were due"]}', NULL, 'payment in arrears / fall in arrears / be in arrears', '[{"en":"The tenant was three months in arrears on the rent.","zh-TW":"租客的租金拖欠了三個月。"},{"en":"Wages paid in arrears means payment follows the work period.","zh-TW":"延後支付的薪資意味著付款在工作期結束後進行。"}]', NULL, NULL, 4, 3426, NULL),
(3427, 'in camera', '/ɪn ˈkæmərə/', 'phrase', '{"zh-TW":["不公開審理；私下進行"],"en":["in private, with the public and press excluded"]}', NULL, 'held in camera / in camera proceedings / in camera review', '[{"en":"The judge ordered an in camera review of the sensitive documents.","zh-TW":"法官下令對敏感文件進行不公開審查。"},{"en":"Testimony involving national security may be heard in camera.","zh-TW":"涉及國家安全的證詞可能不公開進行。"}]', NULL, NULL, 3, 3427, NULL),
(3428, 'in loco parentis', '/ɪn ˌləʊkəʊ pəˈrentɪs/', 'phrase', '{"zh-TW":["代替父母的職責；代親職"],"en":["in the place of a parent; taking on parental responsibility for a child"]}', NULL, 'act in loco parentis / responsibility in loco parentis / in loco parentis doctrine', '[{"en":"Schools act in loco parentis by supervising and protecting students during school hours.","zh-TW":"學校在上學時間代替父母職責，監督和保護學生。"},{"en":"The legal doctrine of in loco parentis assigns certain duties of care to institutions.","zh-TW":"代親職的法律原則為機構分配了某些照顧責任。"}]', NULL, NULL, 5, 3428, NULL),
(3429, 'in-box', '/ˈɪnbɒks/', 'noun', '{"zh-TW":["收件匣；待辦文件匣"],"en":["a container for incoming mail or tasks"]}', NULL, 'clear your in-box / full in-box', '[{"en":"She cleared her in-box before starting the new project.","zh-TW":"她在開始新項目之前清空了收件匣。"},{"en":"His in-box was overflowing with unread emails.","zh-TW":"他的收件匣裝滿了未讀電子郵件。"}]', NULL, NULL, 2, 3429, NULL),
(3430, 'in-depth', 'ɪn dɛpθ', 'adjective', '{"zh-TW":["深入的；徹底的","詳細的"],"en":["thorough and detailed","comprehensive"]}', NULL, 'in-depth analysis/in-depth review', '[{"en":"Please conduct an in-depth analysis.","zh-TW":"請進行深入分析。"}]', '{"adverb":"in depth"}', NULL, 3, 3430, NULL),
(3431, 'in-house', '/ˌɪn ˈhaʊs/', 'adjective', '{"zh-TW":["內部的；公司自有的"],"en":["done or produced within an organization rather than outsourced"]}', NULL, 'in-house team / in-house production / keep in-house', '[{"en":"The company decided to handle legal work in-house rather than outsourcing.","zh-TW":"公司決定在內部處理法律工作而不是外包。"},{"en":"In-house manufacturing gives greater quality control.","zh-TW":"內部製造提供了更大的品質控制。"}]', NULL, NULL, 3, 3431, NULL),
(3432, 'in-network', '/ɪn ˈnɛtwɜːrk/', 'adjective', '{"zh-TW":["網絡內；保險體系內"],"en":["within the group of healthcare providers covered by an insurance plan"]}', NULL, 'in-network provider / in-network hospital', '[{"en":"Using an in-network doctor reduces your costs.","zh-TW":"使用網絡內的醫生可降低您的費用。"},{"en":"Check if the specialist is in-network before making an appointment.","zh-TW":"預約前請確認該專科醫生是否在網絡內。"}]', NULL, NULL, 4, 3432, NULL),
(3433, 'inadequate', '/ɪnˈædɪkwət/', 'adjective', '{"zh-TW":["不足的；不充分的"],"en":["not enough or not good enough"]}', NULL, 'inadequate funding/resources/training', '[{"en":"The budget is inadequate for the project''s needs.","zh-TW":"預算不足以滿足項目需求。"},{"en":"Inadequate training led to the error.","zh-TW":"培訓不足導致了錯誤。"}]', '{"noun":"inadequacy","adjective":"inadequate","adverb":"inadequately"}', NULL, 4, 3433, NULL),
(3434, 'inadvertent', '/''ɪnədˈvɜːrtənt/', 'adjective', '{"zh-TW":["無意的；不故意的"],"en":["not resulting from or achieved through deliberate planning; accidental"]}', NULL, 'inadvertent error / inadvertent consequence / inadvertent disclosure', '[{"en":"The inadvertent disclosure of confidential information led to a data breach investigation.","zh-TW":"機密信息的無意披露導致了一次數據洩露調查。"},{"en":"An inadvertent error in the budget spreadsheet resulted in a significant miscalculation.","zh-TW":"預算電子表格中的無意錯誤導致了重大計算錯誤。"}]', '{"adverb":"inadvertently"}', NULL, 4, 3434, NULL),
(3435, 'inadvertently', '/''ɪnədˈvɜːrtəntli/', 'adverb', '{"zh-TW":["無意中；不經意地"],"en":["without intention; accidentally"]}', NULL, 'inadvertently caused / inadvertently revealed / inadvertently overlooked', '[{"en":"She inadvertently sent the confidential email to the wrong recipient.","zh-TW":"她無意中將機密郵件發送給了錯誤的收件人。"},{"en":"The update inadvertently broke several key features of the software.","zh-TW":"這次更新無意中破壞了軟體的幾個關鍵功能。"}]', '{"adjective":"inadvertent"}', NULL, 5, 3435, NULL),
(3436, 'inaugural', '/''ɪˌnɔːɡjərəl/', 'adjective', '{"zh-TW":["就職的；開幕的；首次的"],"en":["marking the beginning of an institution, activity, or period of office"]}', NULL, 'inaugural speech / inaugural ceremony / inaugural event', '[{"en":"The president''s inaugural speech outlined her vision for the country.","zh-TW":"總統的就職演說概述了她對國家的願景。"},{"en":"She attended the inaugural ceremony of the new cultural center.","zh-TW":"她出席了新文化中心的開幕典禮。"}]', '{"verb":"inaugurate","noun":"inauguration"}', NULL, 3, 3436, NULL),
(3437, 'inbound logistics', '/ˈɪnbaʊnd ləˈdʒɪstɪks/', 'noun', '{"zh-TW":["進貨物流；入站物流"],"en":["the management of incoming raw materials and goods from suppliers"]}', NULL, 'optimize inbound logistics / inbound logistics cost', '[{"en":"Streamlining inbound logistics cut warehouse receiving time in half.","zh-TW":"簡化進貨物流將倉庫收貨時間縮短了一半。"},{"en":"Inbound logistics efficiency is critical for just-in-time manufacturing.","zh-TW":"進貨物流效率對即時生產至關重要。"}]', NULL, NULL, 5, 3437, NULL),
(3438, 'incentive', '/ɪnˈsentɪv/', 'noun', '{"zh-TW":["激勵；獎勵；動機"],"en":["something that encourages a person to do something"]}', NULL, 'financial/tax incentive / provide an incentive', '[{"en":"The company offers incentives to attract new employees.","zh-TW":"公司提供激勵措施來吸引新員工。"},{"en":"Tax incentives encourage business investment.","zh-TW":"稅收優惠鼓勵企業投資。"}]', '{"noun":"incentive","verb":"incentivize"}', NULL, 3, 3438, 135),
(3439, 'incentive alignment', '/ɪnˈsentɪv əˈlaɪnmənt/', 'noun', '{"zh-TW":["激勵對齊"],"en":["ensuring the incentives of different parties push them toward the same goals"]}', NULL, 'achieve incentive alignment / incentive alignment problem / improve incentive alignment', '[{"en":"Incentive alignment between management and shareholders reduces agency costs.","zh-TW":"管理層與股東之間的激勵對齊降低了代理成本。"},{"en":"Bonus structures must be designed with incentive alignment in mind.","zh-TW":"獎金結構必須以激勵對齊為設計原則。"}]', NULL, NULL, 5, 3439, NULL),
(3440, 'incentive bonus', '/ɪnˈsentɪv ˈboʊnəs/', 'noun', '{"zh-TW":["激勵獎金"],"en":["extra pay awarded for meeting or exceeding performance targets"]}', NULL, 'earn an incentive bonus / award an incentive bonus', '[{"en":"Sales staff receive an incentive bonus when they exceed their quota.","zh-TW":"銷售人員超額完成指標時獲得激勵獎金。"},{"en":"The incentive bonus scheme improved team motivation significantly.","zh-TW":"激勵獎金計劃顯著提高了團隊積極性。"}]', NULL, NULL, 5, 3440, NULL),
(3441, 'incentive pay', '/ɪnˈsɛntɪv peɪ/', 'noun', '{"zh-TW":["績效獎金；激勵薪酬"],"en":["additional pay given to motivate employees"]}', NULL, 'receive incentive pay / incentive pay structure', '[{"en":"Incentive pay is tied to achieving quarterly sales targets.","zh-TW":"績效獎金與完成季度銷售目標掛鈎。"},{"en":"The company introduced incentive pay to boost productivity.","zh-TW":"公司引入績效獎金以提升生產力。"}]', NULL, NULL, 5, 3441, NULL),
(3442, 'incentive plan', '/ɪnˈsentɪv plæn/', 'noun', '{"zh-TW":["激勵計劃"],"en":["a structured program offering rewards to motivate desired employee behavior"]}', NULL, 'design an incentive plan / implement an incentive plan', '[{"en":"The incentive plan linked bonuses to individual and team performance goals.","zh-TW":"激勵計劃將獎金與個人和團隊績效目標掛鈎。"},{"en":"A well-structured incentive plan improves productivity and reduces turnover.","zh-TW":"結構良好的激勵計劃提高了生產力並降低了員工流動率。"}]', '{"synonym":"incentive scheme"}', NULL, 5, 3442, NULL),
(3443, 'incentive scheme', '/ɪnˈsentɪv skiːm/', 'noun', '{"zh-TW":["激勵計劃；獎勵制度"],"en":["a structured program offering rewards for achieving defined goals"]}', NULL, 'design an incentive scheme / launch an incentive scheme', '[{"en":"The new incentive scheme doubled the sales team average performance.","zh-TW":"新激勵計劃使銷售團隊的平均績效翻倍了。"},{"en":"An effective incentive scheme aligns individual goals with company objectives.","zh-TW":"有效的激勵計劃使個人目標與公司目標保持一致。"}]', NULL, NULL, 5, 3443, NULL),
(3444, 'incentive structure', '/''ɪnˌsentɪv ˌstrʌktʃər/', 'noun', '{"zh-TW":["激勵結構"],"en":["the system of rewards and penalties designed to motivate individuals or organizations toward desired behaviors"]}', NULL, 'design an incentive structure / align the incentive structure / flawed incentive structure', '[{"en":"A well-designed incentive structure encourages employees to work toward company goals.","zh-TW":"設計良好的激勵結構鼓勵員工朝著公司目標努力。"},{"en":"The research found that the incentive structure in the sales department led to unethical behavior.","zh-TW":"研究發現，銷售部門的激勵結構導致了不道德行為。"}]', '{"noun":"incentive"}', NULL, 5, 3444, NULL),
(3445, 'incentivize', '/ɪnˈsentɪvaɪz/', 'verb', '{"zh-TW":["激勵；提供獎勵"],"en":["to provide incentives to encourage action"]}', NULL, 'incentivize employees/performance', '[{"en":"The program incentivizes employees to meet targets.","zh-TW":"該計劃激勵員工達成目標。"},{"en":"Tax breaks incentivize green energy investment.","zh-TW":"稅收優惠激勵綠色能源投資。"}]', '{"noun":"incentive","verb":"incentivize"}', NULL, 4, 3445, 692),
(3446, 'inception', '/ɪnˈsepʃən/', 'noun', '{"zh-TW":["開始；創立"],"en":["the start or establishment of an organization or project"]}', NULL, 'since inception / date of inception / from inception to completion', '[{"en":"The company has grown steadily since its inception in 2010.","zh-TW":"公司自2010年創立以來一直穩定增長。"},{"en":"The project was completed ahead of schedule from inception.","zh-TW":"項目從一開始就提前完成了。"}]', '{"verb":"incept"}', NULL, 3, 3446, NULL),
(3447, 'incessant', '/''ɪnˌsesənt/', 'adjective', '{"zh-TW":["不停的；持續的"],"en":["never ending or always happening; continuing without pause or interruption"]}', NULL, 'incessant noise / incessant demands / incessant rain', '[{"en":"The incessant noise from the construction site made it impossible to concentrate.","zh-TW":"建築工地不停的噪音使人無法集中注意力。"},{"en":"She complained about the incessant demands placed on her time by her job.","zh-TW":"她抱怨工作對她時間的不停要求。"}]', '{"adverb":"incessantly","noun":"incessance"}', NULL, 3, 3447, NULL),
(3448, 'incessantly', '/''ɪnˈsesəntli/', 'adverb', '{"zh-TW":["不斷地；無休止地"],"en":["without stopping; constantly"]}', NULL, 'complain incessantly / work incessantly / talk incessantly', '[{"en":"She worked incessantly to meet the tight project deadline.","zh-TW":"她不斷地工作以達到緊迫的項目截止日期。"},{"en":"The machine ran incessantly for three days to complete the production order.","zh-TW":"機器不間斷地運行了三天以完成生產訂單。"}]', '{"adjective":"incessant"}', NULL, 4, 3448, NULL),
(3449, 'incidence', '/ˈɪnsɪdəns/', 'noun', '{"zh-TW":["發生率"],"en":["the rate at which something occurs"]}', NULL, 'high/low incidence of', '[{"en":"There is a high incidence of diabetes in this region.","zh-TW":"該地區糖尿病發生率很高。"},{"en":"The incidence of workplace injuries has decreased.","zh-TW":"工傷事故發生率已經下降。"}]', '{"noun":"incidence, incident","adjective":"incidental"}', NULL, 3, 3449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3450, 'incident', '/ˈɪnsɪdənt/', 'noun', '{"zh-TW":["事件；事故"],"en":["an event, especially one that is unusual or unpleasant"]}', NULL, 'report an incident / security incident', '[{"en":"The incident was reported to the police.","zh-TW":"該事件已報告給警方。"},{"en":"Several minor incidents occurred during the event.","zh-TW":"活動期間發生了幾起小事故。"}]', '{"noun":"incident, incidence","adjective":"incidental","adverb":"incidentally"}', NULL, 3, 3450, NULL),
(3451, 'incident report', '/ˈɪnsɪdənt rɪˈpɔːrt/', 'noun', '{"zh-TW":["事件報告"],"en":["a document describing an unusual event at work"]}', NULL, 'submit an incident report / complete an incident report', '[{"en":"All incidents, however minor, must be documented in an incident report.","zh-TW":"所有事件，無論多小，都必須記錄在事件報告中。"},{"en":"The incident report was submitted to the safety committee.","zh-TW":"事件報告已提交給安全委員會。"}]', NULL, NULL, 5, 3451, NULL),
(3452, 'incline', '/ɪnˈklaɪn/', 'verb', '{"zh-TW":["傾向；使傾斜"],"en":["to tend toward; to lean"]}', NULL, 'inclined to agree / be inclined to', '[{"en":"I am inclined to accept the offer.","zh-TW":"我傾向於接受這個提議。"},{"en":"Management is inclined to approve the budget.","zh-TW":"管理層傾向於批准預算。"}]', '{"noun":"inclination","verb":"incline","adjective":"inclined"}', NULL, 3, 3452, NULL),
(3453, 'include', '/ɪnˈkluːd/', 'verb', '{"zh-TW":["包括；包含"],"en":["to contain as part of a whole"]}', NULL, 'include information/details', '[{"en":"The price includes tax and delivery.","zh-TW":"價格包括稅金和運費。"},{"en":"Please include your contact details in the application.","zh-TW":"請在申請中包含您的聯繫方式。"}]', '{"noun":"inclusion","verb":"include","adjective":"inclusive, included"}', NULL, 3, 3453, NULL),
(3454, 'inclusion', '/ɪnˈkluːʒən/', 'noun', '{"zh-TW":["包容性；納入"],"en":["creating an environment where everyone feels valued and respected"]}', NULL, 'diversity and inclusion / foster inclusion / inclusion policy', '[{"en":"Inclusion initiatives made employees feel more valued.","zh-TW":"包容性倡議使員工感到更受重視。"},{"en":"The company scored highly on inclusion in its employee survey.","zh-TW":"公司在員工調查的包容性指標上得分很高。"}]', '{"adjective":"inclusive","verb":"include"}', NULL, 3, 3454, NULL),
(3455, 'inclusive', '/''ɪnˌkluːsɪv/', 'adjective', '{"zh-TW":["包容的；包含廣泛的"],"en":["not excluding any section of society or any party involved in something"]}', NULL, 'inclusive policy / inclusive design / inclusive environment', '[{"en":"An inclusive workplace values diversity and ensures everyone has equal opportunities.","zh-TW":"包容性的工作場所重視多樣性，確保每個人都有平等的機會。"},{"en":"Inclusive design makes products and services accessible to people with disabilities.","zh-TW":"包容性設計使殘障人士能夠使用產品和服務。"}]', '{"adverb":"inclusively","noun":"inclusion","noun2":"inclusivity"}', NULL, 3, 3455, NULL),
(3456, 'income', '/ˈɪnkʌm/', 'noun', '{"zh-TW":["收入；所得"],"en":["money received from work or investments"]}', NULL, 'annual/monthly income / income tax', '[{"en":"Her annual income exceeds $80,000.","zh-TW":"她的年收入超過8萬美元。"},{"en":"Income tax rates vary by bracket.","zh-TW":"所得稅稅率因級距而異。"}]', '{"noun":"income"}', NULL, 2, 3456, NULL),
(3457, 'income distribution', '/ˈɪnkʌm ˌdɪstrɪˈbjuːʃən/', 'noun', '{"zh-TW":["收入分配；所得分佈"],"en":["how total income is spread among individuals or within an organization"]}', NULL, 'review income distribution / unequal income distribution', '[{"en":"The income distribution policy ensures all tiers receive fair compensation.","zh-TW":"收入分配政策確保所有層級獲得公平報酬。"},{"en":"Widening income distribution creates social and economic challenges.","zh-TW":"擴大的收入分配差距造成了社會和經濟挑戰。"}]', NULL, NULL, 5, 3457, NULL),
(3458, 'income inequality', '/ˈɪnkʌm ˌɪnɪˈkwɒlɪti/', 'noun', '{"zh-TW":["收入不平等"],"en":["the unequal distribution of income across members of a society"]}', NULL, 'rising income inequality / measure income inequality / address income inequality', '[{"en":"Income inequality has widened in many developed economies over the past three decades.","zh-TW":"在過去三十年中，許多已開發經濟體的收入不平等有所加劇。"},{"en":"High income inequality reduces social cohesion and political stability.","zh-TW":"高度收入不平等降低社會凝聚力和政治穩定性。"}]', NULL, NULL, 5, 3458, NULL),
(3459, 'income statement', '/ˈɪnkʌm ˈsteɪtmənt/', 'noun', '{"zh-TW":["損益表；收益表"],"en":["a financial report showing revenues, expenses, and profit over a period"]}', NULL, 'quarterly income statement / read the income statement', '[{"en":"The income statement revealed a 10% increase in revenue.","zh-TW":"損益表顯示收入增加了10%。"},{"en":"Analysts focused on the income statement for profitability clues.","zh-TW":"分析師關注損益表以尋找盈利線索。"}]', '{"alternative":"profit and loss statement"}', NULL, 5, 3459, NULL),
(3460, 'income tax', '/ˈɪnkʌm tæks/', 'noun', '{"zh-TW":["所得稅"],"en":["a tax levied on individuals or organizations based on income or profit"]}', NULL, 'income tax rate / pay income tax / income tax return / corporate income tax', '[{"en":"Corporate income tax is charged at 25% under the new rules.","zh-TW":"根據新規定，企業所得稅率為25%。"},{"en":"The company filed its income tax return before the deadline.","zh-TW":"公司在截止日期前申報了所得稅。"}]', NULL, NULL, 4, 3460, NULL),
(3461, 'income tax return', '/ˈɪnkʌm tæks rɪˈtɜːrn/', 'noun', '{"zh-TW":["所得稅申報單"],"en":["a form filed with the tax authority reporting income and tax owed"]}', NULL, 'file an income tax return / annual income tax return', '[{"en":"All employees must file an income tax return by April 30th.","zh-TW":"所有員工必須在4月30日前申報所得稅。"},{"en":"An accountant helped her complete the income tax return accurately.","zh-TW":"會計師幫助她準確完成了所得稅申報單。"}]', NULL, NULL, 5, 3461, NULL),
(3462, 'incommensurable', '/ˌɪnkəˈmenʃərəbəl/', 'adjective', '{"zh-TW":["不可比較的；無公度的"],"en":["having no common measure; impossible to measure or judge by the same standards"]}', NULL, 'incommensurable values / incommensurable frameworks / incommensurable theories', '[{"en":"Critics argue that competing paradigms are incommensurable.","zh-TW":"批評者認為競爭的範例是不可比較的。"},{"en":"Some philosophers believe that cultural values are incommensurable across societies.","zh-TW":"一些哲學家認為文化價值觀在不同社會之間是不可比較的。"}]', '{"noun":"incommensurability"}', NULL, 5, 3462, NULL),
(3463, 'inconvenience', '/ˌɪnkənˈviːniəns/', 'noun, verb', '{"zh-TW":["不便；麻煩"],"en":["trouble or difficulty caused to someone"]}', NULL, 'cause/apologize for the inconvenience', '[{"en":"We apologize for any inconvenience caused.","zh-TW":"對造成的任何不便，我們深表歉意。"},{"en":"The construction work may inconvenience residents.","zh-TW":"施工可能會給居民帶來不便。"}]', '{"noun":"inconvenience","adjective":"inconvenient","verb":"inconvenience"}', NULL, 5, 3463, NULL),
(3464, 'incorporate', '/ɪnˈkɔːrpəreɪt/', 'verb', '{"zh-TW":["納入；合併","成立公司"],"en":["to include as part of something","to form a legal corporation"]}', NULL, 'incorporate feedback/changes/features', '[{"en":"We incorporated customer feedback into the new design.","zh-TW":"我們將客戶反饋納入新設計中。"},{"en":"The business was incorporated in 2020.","zh-TW":"這家企業於2020年註冊成立。"}]', '{"noun":"incorporation","verb":"incorporate","adjective":"incorporated"}', NULL, 4, 3464, 369),
(3465, 'incoterms', '/ˈɪnkəʊtɜːrmz/', 'noun', '{"zh-TW":["國際貿易術語"],"en":["internationally recognized trade terms defining responsibilities"]}', NULL, 'specify incoterms / FOB incoterms', '[{"en":"The contract specified CIF incoterms for this shipment.","zh-TW":"合約規定了本次貨運使用CIF國際貿易術語。"},{"en":"Understanding incoterms prevents disputes over shipping costs.","zh-TW":"了解國際貿易術語可防止運費方面的爭議。"}]', NULL, NULL, 3, 3465, NULL),
(3466, 'increase', '/ɪnˈkriːs/', 'verb, noun', '{"zh-TW":["增加；提高"],"en":["to become or make greater in amount"]}', NULL, 'increase in sales/demand / a significant increase', '[{"en":"Sales increased by 20% last quarter.","zh-TW":"上季度銷售額增長了20%。"},{"en":"There has been a steady increase in demand.","zh-TW":"需求持續穩定增長。"}]', '{"noun":"increase","verb":"increase","adjective":"increasing","adverb":"increasingly"}', NULL, 3, 3466, 136),
(3467, 'increase market share', '/ɪnˈkriːs ˈmɑːrkɪt ʃeər/', 'verb', '{"zh-TW":["增加市場份額"],"en":["to grow the percentage of total sales in a market held by a company"]}', NULL, 'strategy to increase market share / increase market share aggressively', '[{"en":"The company reduced prices to increase market share.","zh-TW":"公司降價以增加市場份額。"},{"en":"Innovative products helped the firm increase market share rapidly.","zh-TW":"創新產品幫助公司迅速增加了市場份額。"}]', NULL, NULL, 5, 3467, NULL),
(3468, 'incremental', '/ˌɪŋkrəˈmentəl/', 'adjective', '{"zh-TW":["漸進的；逐步的"],"en":["made in small progressive steps rather than all at once"]}', NULL, 'incremental improvement / incremental cost / incremental change', '[{"en":"The company adopted incremental improvements rather than major overhaul.","zh-TW":"公司採用了漸進式改進而非重大改革。"},{"en":"Incremental cost increases are easier to absorb than sudden rises.","zh-TW":"漸進式成本增加比突然上漲更容易消化。"}]', '{"adverb":"incrementally","noun":"increment"}', NULL, 4, 3468, 883),
(3469, 'incremental cost', '/ˌɪnkrɪˈmentəl kɒst/', 'noun', '{"zh-TW":["增量成本；邊際成本"],"en":["the additional cost incurred by producing one more unit of a product or service"]}', NULL, 'calculate incremental cost / incremental cost analysis', '[{"en":"The incremental cost of producing one more batch was $800.","zh-TW":"再生產一批的增量成本為800元。"},{"en":"Pricing decisions should consider incremental cost versus marginal revenue.","zh-TW":"定價決策應考慮增量成本與邊際收入的關係。"}]', NULL, NULL, 5, 3469, NULL),
(3470, 'incremental innovation', '/ˌɪŋkrɪˈmentəl ˌɪnəˈveɪʃən/', 'noun', '{"zh-TW":["漸進式創新"],"en":["small, continuous improvements made to existing products or processes"]}', NULL, 'pursue incremental innovation / incremental innovation strategy / balance incremental innovation', '[{"en":"Most innovation in established companies is incremental rather than disruptive.","zh-TW":"老牌公司的大多數創新是漸進式的而非顛覆性的。"},{"en":"Incremental innovation keeps products competitive without high development risk.","zh-TW":"漸進式創新使產品保持競爭力而無需高開發風險。"}]', NULL, NULL, 5, 3470, NULL),
(3471, 'incumbency advantage', '/ɪnˈkʌmbənsi ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["現任者優勢"],"en":["the structural benefits enjoyed by an established firm or politician over challengers"]}', NULL, 'incumbency advantage in politics / incumbency advantage in markets / overcome incumbency advantage', '[{"en":"Brand loyalty and switching costs give large platforms a significant incumbency advantage.","zh-TW":"品牌忠誠度和轉換成本使大型平臺具有顯著的現任者優勢。"},{"en":"The incumbency advantage in electoral politics makes it difficult to unseat long-serving representatives.","zh-TW":"選舉政治中的現任者優勢使長期任職的代表難以被取代。"}]', NULL, NULL, 5, 3471, NULL),
(3472, 'incumbent', '/ɪnˈkʌmbənt/', 'adjective, noun', '{"zh-TW":["現任的；在職者","義不容辭的"],"en":["currently holding office; necessary as a duty","the current holder of a position"]}', NULL, 'incumbent president / incumbent upon', '[{"en":"It is incumbent upon management to ensure safety.","zh-TW":"管理層有義務確保安全。"},{"en":"The incumbent CEO has been in the role for five years.","zh-TW":"現任執行長已在職五年。"}]', '{"noun":"incumbent, incumbency","adjective":"incumbent"}', NULL, 3, 3472, NULL),
(3473, 'incur', '/ɪnˈkɜːr/', 'verb', '{"zh-TW":["招致；產生（費用、債務）"],"en":["to become subject to something unpleasant as a result of an action"]}', NULL, 'incur costs/expenses/debt/losses', '[{"en":"The company incurred significant losses last year.","zh-TW":"公司去年遭受了重大損失。"},{"en":"You may incur additional charges for late payment.","zh-TW":"逾期付款可能會產生額外費用。"}]', '{"noun":"incurrence","verb":"incur"}', NULL, 2, 3473, 693),
(3474, 'indebted', '/ɪnˈdetɪd/', 'adjective', '{"zh-TW":["負債的；感激的"],"en":["owing money; also feeling gratitude to someone"]}', NULL, 'heavily indebted / financially indebted / indebted to a creditor', '[{"en":"The highly indebted company sought to refinance its loans.","zh-TW":"這家高度負債的公司尋求對貸款進行再融資。"},{"en":"We are indebted to our partners for their continued support.","zh-TW":"我們感謝合作夥伴持續的支持。"}]', '{"noun":"indebtedness"}', NULL, 3, 3474, NULL),
(3475, 'indebtedness', '/ɪnˈdetɪdnəs/', 'noun', '{"zh-TW":["負債；債務"],"en":["the total amount owed by a company or individual"]}', NULL, 'level of indebtedness / reduce indebtedness', '[{"en":"High indebtedness limits the company''s ability to invest in growth.","zh-TW":"高負債限制了公司投資增長的能力。"},{"en":"The restructuring plan reduced total indebtedness by 30%.","zh-TW":"重組計劃將總負債減少了30%。"}]', '{"adjective":"indebted"}', NULL, 4, 3475, NULL),
(3476, 'indemnification', '/ɪnˌdɛmnɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["賠償；保障"],"en":["the action of compensating for loss or damage"]}', NULL, 'indemnification clause / seek indemnification', '[{"en":"The contract includes an indemnification clause for third-party claims.","zh-TW":"合約包含第三方索賠的賠償條款。"},{"en":"The company agreed to indemnification for any losses incurred.","zh-TW":"公司同意對所發生的任何損失進行賠償。"}]', '{"verb":"indemnify","noun":"indemnity"}', NULL, 5, 3476, 794),
(3477, 'indemnification clause', '/ɪnˌdemnɪfɪˈkeɪʃən klɔːz/', 'noun', '{"zh-TW":["賠償條款；補償條款"],"en":["a contract provision requiring one party to compensate another for losses or damages"]}', NULL, 'include an indemnification clause / negotiate indemnification clause', '[{"en":"The indemnification clause protected the contractor from third-party claims.","zh-TW":"賠償條款保護了承包商免受第三方索賠。"},{"en":"Both parties agreed on a mutual indemnification clause in the agreement.","zh-TW":"雙方在協議中同意了相互賠償條款。"}]', NULL, NULL, 5, 3477, NULL),
(3478, 'indemnify', '/ɪnˈdɛmnɪfaɪ/', 'verb', '{"zh-TW":["賠償；保障免於損失"],"en":["to compensate for harm or loss; to protect from liability"]}', NULL, 'agree to indemnify / indemnify against loss', '[{"en":"The supplier agreed to indemnify the buyer against defective products.","zh-TW":"供應商同意就有問題的產品對買方進行賠償。"},{"en":"The contract includes a clause to indemnify both parties.","zh-TW":"合約包含保障雙方免於損失的條款。"}]', '{"noun":"indemnification","noun2":"indemnity"}', NULL, 3, 3478, NULL),
(3479, 'indemnity', '/ɪnˈdemnɪti/', 'noun', '{"zh-TW":["賠償；免責"],"en":["security against loss or damage; compensation for harm suffered"]}', NULL, 'indemnity clause / indemnity agreement / hold harmless indemnity', '[{"en":"The contract includes an indemnity clause protecting the client.","zh-TW":"合約包含保護客戶的賠償條款。"},{"en":"The insurance policy provides indemnity against business interruption.","zh-TW":"保險單提供針對業務中斷的賠償。"}]', '{"verb":"indemnify","adjective":"indemnified"}', NULL, 3, 3479, NULL),
(3480, 'indemnity clause', '/ɪnˈdemnɪti klɔːz/', 'noun', '{"zh-TW":["賠償條款；免責條款"],"en":["a contract provision requiring one party to compensate the other for specified losses"]}', NULL, 'include an indemnity clause / enforce the indemnity clause', '[{"en":"The indemnity clause required the supplier to cover third-party claims.","zh-TW":"賠償條款要求供應商承擔第三方索賠。"},{"en":"An indemnity clause protects the service provider against consequential damages.","zh-TW":"賠償條款保護服務提供商免受間接損害。"}]', '{"noun":"indemnification","verb":"indemnify"}', NULL, 5, 3480, NULL),
(3481, 'indenture', '/ɪnˈdentʃər/', 'noun', '{"zh-TW":["契約；債券信託契約"],"en":["a formal agreement or contract; specifically, the legal agreement governing a bond"]}', NULL, 'bond indenture / loan indenture / indenture trustee', '[{"en":"The indenture specifies the covenants that the issuer must honor.","zh-TW":"契約規定了發行人必須遵守的條款。"},{"en":"Bondholders'' rights are defined in the indenture agreement.","zh-TW":"債券持有人的權利在契約協議中定義。"}]', '{"verb":"indenture"}', NULL, 3, 3481, NULL),
(3482, 'independent', 'ˌɪndɪˈpɛndənt', 'adjective', '{"zh-TW":["獨立的；自主的","自立的"],"en":["not relying on others","self-governing"]}', NULL, 'independent review/independent worker', '[{"en":"She works independently and efficiently.","zh-TW":"她獨立而高效地工作。"}]', '{"noun":"independence","adverb":"independently"}', NULL, 4, 3482, NULL),
(3483, 'independent contractor', '/ˌɪndɪˈpendənt kənˈtræktər/', 'noun', '{"zh-TW":["獨立承包商；自由接案者"],"en":["a self-employed worker who provides services under contract"]}', NULL, 'hire an independent contractor / work as an independent contractor', '[{"en":"The company hired independent contractors to avoid long-term employment costs.","zh-TW":"公司聘用了獨立承包商以避免長期雇傭成本。"},{"en":"Independent contractors are responsible for their own taxes and benefits.","zh-TW":"獨立承包商負責自己的稅務和福利。"}]', NULL, NULL, 5, 3483, NULL),
(3484, 'independent review', '/ˌɪndɪˈpendənt rɪˈvjuː/', 'noun', '{"zh-TW":["獨立審查"],"en":["an assessment conducted by an outside party with no conflicts of interest"]}', NULL, 'commission an independent review / independent review findings', '[{"en":"An independent review confirmed the accuracy of the company accounts.","zh-TW":"獨立審查確認了公司帳目的準確性。"},{"en":"The board commissioned an independent review after the allegations.","zh-TW":"董事會在指控後委託了獨立審查。"}]', NULL, NULL, 5, 3484, NULL),
(3485, 'independent study', '/''ɪndɪˌpendənt ˌstʌdi/', 'noun', '{"zh-TW":["自主學習；獨立研究"],"en":["a form of education where students work at their own pace, often without direct supervision"]}', NULL, 'pursue independent study / independent study program / benefit of independent study', '[{"en":"She completed the research through independent study over the summer break.","zh-TW":"她在暑假期間通過自主學習完成了研究。"},{"en":"Independent study develops self-discipline and time management skills in students.","zh-TW":"自主學習培養了學生的自律和時間管理能力。"}]', '{"adjective":"independent"}', NULL, 5, 3485, NULL),
(3486, 'independent variable', '/ˌɪndɪˈpendənt ˈveəriəbəl/', 'noun', '{"zh-TW":["自變量；獨立變量"],"en":["a variable that is manipulated or changed in an experiment"]}', NULL, 'control the independent variable / identify the independent variable / independent variable selection', '[{"en":"The researcher varied the independent variable to observe its effect.","zh-TW":"研究員改變自變量以觀察其效果。"},{"en":"The independent variable in this study was the dosage of the drug.","zh-TW":"本研究中的自變量是藥物劑量。"}]', NULL, NULL, 5, 3486, NULL),
(3487, 'index', '/ˈɪndeks/', 'noun, verb', '{"zh-TW":["指數；索引"],"en":["a system showing changes in value; an alphabetical list"]}', NULL, 'stock/price index / consumer price index', '[{"en":"The consumer price index rose by 3%.","zh-TW":"消費者物價指數上漲了3%。"},{"en":"Check the index at the back of the book.","zh-TW":"查看書後的索引。"}]', '{"noun":"index","verb":"index"}', NULL, 2, 3487, NULL),
(3488, 'index fund', '/ˈɪndeks fʌnd/', 'noun', '{"zh-TW":["指數基金"],"en":["a type of mutual fund designed to replicate the performance of a market index"]}', NULL, 'invest in an index fund / low-cost index fund', '[{"en":"Index funds offer broad market exposure at lower fees than active funds.","zh-TW":"指數基金以低於主動管理基金的費用提供廣泛的市場敞口。"},{"en":"Long-term investors often prefer index funds for their consistent returns.","zh-TW":"長期投資者通常偏好指數基金，因為其一致的回報。"}]', NULL, NULL, 4, 3488, NULL),
(3489, 'indicate', '/ˈɪndɪkeɪt/', 'verb', '{"zh-TW":["指示；表明"],"en":["to point out or show"]}', NULL, 'indicate that / clearly indicate', '[{"en":"The survey indicates that customer satisfaction has improved.","zh-TW":"調查顯示客戶滿意度有所提高。"},{"en":"Red lights indicate danger.","zh-TW":"紅燈表示危險。"}]', '{"noun":"indication, indicator","verb":"indicate","adjective":"indicative"}', NULL, 3, 3489, 34),
(3490, 'indicative pricing', '/ɪnˈdɪkətɪv ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["指示性定價"],"en":["a non-binding estimate of the price at which a transaction may be completed"]}', NULL, 'provide indicative pricing / indicative pricing range / based on indicative pricing', '[{"en":"The bank provided indicative pricing for the bond issuance.","zh-TW":"銀行為債券發行提供了指示性定價。"},{"en":"Indicative pricing helps sellers gauge market interest before formal launch.","zh-TW":"指示性定價幫助賣家在正式發布前衡量市場興趣。"}]', NULL, NULL, 5, 3490, NULL),
(3491, 'indict', '/ɪnˈdaɪt/', 'verb', '{"zh-TW":["起訴；控告"],"en":["to formally charge someone with a crime"]}', NULL, 'indict on charges / grand jury indictment', '[{"en":"He was indicted on fraud charges.","zh-TW":"他被以詐欺罪起訴。"},{"en":"The grand jury issued an indictment.","zh-TW":"大陪審團發出了起訴書。"}]', '{"noun":"indictment"}', NULL, 2, 3491, NULL),
(3492, 'indictment', '/ɪnˈdaɪtmənt/', 'noun', '{"zh-TW":["起訴書；起訴"],"en":["a formal charge or accusation of a serious crime"]}', NULL, 'return an indictment / issue an indictment / criminal indictment', '[{"en":"The grand jury returned an indictment against the corporate executives.","zh-TW":"大陪審團對企業高管提出了起訴。"},{"en":"An indictment does not prove guilt but enables a criminal trial.","zh-TW":"起訴書不能證明有罪，但可以啟動刑事審判。"}]', '{"verb":"indict","adjective":"indicted"}', NULL, 4, 3492, NULL),
(3493, 'indie', '/ˈɪndi/', 'adjective', '{"zh-TW":["獨立的；非主流的"],"en":["(of music, film, etc.) produced independently from a major commercial company"]}', NULL, 'indie film / indie music / indie game', '[{"en":"The indie film won critical acclaim despite its modest budget.","zh-TW":"這部獨立電影儘管預算有限，仍獲得了評論界的讚譽。"},{"en":"Streaming platforms have given indie artists access to global audiences.","zh-TW":"串流媒體平台讓獨立藝術家能夠接觸到全球受眾。"}]', '{"noun":"indie"}', NULL, 2, 3493, NULL),
(3494, 'indigenous', '/ɪnˈdɪdʒənəs/', 'adjective', '{"zh-TW":["本土的；原住民的"],"en":["originating in a particular place"]}', NULL, 'indigenous people/culture/species', '[{"en":"The project respects indigenous land rights.","zh-TW":"該項目尊重原住民的土地權利。"},{"en":"Indigenous plants are used in the garden design.","zh-TW":"花園設計中使用了本土植物。"}]', '{"noun":"indigenous","adjective":"indigenous"}', NULL, 4, 3494, NULL),
(3495, 'indigent', '/ˈɪndɪdʒənt/', 'adjective', '{"zh-TW":["貧困的；貧窮的"],"en":["suffering from extreme poverty; having insufficient income"]}', NULL, 'indigent population / indigent defendant / assist the indigent', '[{"en":"Legal aid services provide representation for indigent defendants who cannot afford counsel.","zh-TW":"法律援助服務為無力支付律師費的貧困被告提供代理。"},{"en":"The charity distributes meals to indigent residents of the city every day.","zh-TW":"該慈善機構每天向市內的貧困居民分發餐食。"}]', '{"noun":"indigence"}', NULL, 3, 3495, NULL),
(3496, 'indignant', '/''ɪnˈdɪɡnənt/', 'adjective', '{"zh-TW":["憤憤不平的；義憤的"],"en":["feeling or showing anger or annoyance at what is perceived as unfair treatment"]}', NULL, 'indignant reaction / rightfully indignant / become indignant', '[{"en":"She was indignant when she discovered she had been passed over for the promotion.","zh-TW":"當她發現自己被跳過沒有獲得晉升時，她感到憤憤不平。"},{"en":"The team was indignant about the sudden policy change without consultation.","zh-TW":"團隊對未經協商的突然政策改變感到義憤填膺。"}]', '{"adverb":"indignantly","noun":"indignation"}', NULL, 3, 3496, NULL),
(3497, 'indirect cost', '/ˌɪndɪˈrekt kɒst/', 'noun', '{"zh-TW":["間接成本"],"en":["costs not directly tied to producing a specific product or service"]}', NULL, 'allocate indirect costs / indirect cost analysis', '[{"en":"Rent and administrative salaries are classified as indirect costs.","zh-TW":"租金和行政薪資被歸類為間接成本。"},{"en":"Indirect costs must be allocated fairly across product lines.","zh-TW":"間接成本必須在各產品線中公平分配。"}]', '{"opposite":"direct cost"}', NULL, 5, 3497, NULL),
(3498, 'indirect tax', '/ˌɪndɪˈrekt tæks/', 'noun', '{"zh-TW":["間接稅"],"en":["a tax collected by an intermediary from the consumer, such as VAT or sales tax"]}', NULL, 'pay indirect tax / indirect tax rate', '[{"en":"Value-added tax is the most common form of indirect tax.","zh-TW":"增值稅是最常見的間接稅形式。"},{"en":"Indirect taxes are regressive as they take a higher proportion of lower incomes.","zh-TW":"間接稅具有累退性，因為它們佔低收入較高的比例。"}]', '{"opposite":"direct tax"}', NULL, 4, 3498, NULL),
(3499, 'indispensable', '/''ɪndɪˈspensəbəl/', 'adjective', '{"zh-TW":["不可缺少的；必不可少的"],"en":["absolutely necessary; not able to be done without"]}', NULL, 'indispensable tool / indispensable member / indispensable skill', '[{"en":"Strong communication skills are indispensable for any leadership role.","zh-TW":"強大的溝通技能對任何領導職位都是不可或缺的。"},{"en":"She quickly became an indispensable member of the research team.","zh-TW":"她很快成為研究團隊不可或缺的成員。"}]', '{"adverb":"indispensably"}', NULL, 5, 3499, NULL);